settings.custom_css:
selector .elementor-container {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: stretch !important;
}
selector .elementor-row {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: stretch !important;
}
selector .elementor-column {
  display: flex !important;
  height: auto !important;
}

selector {
  display: flex !important;
  flex-direction: column !important;
  height: 100% !important;
}
selector > .elementor-widget-wrap {
  display: flex !important;
  flex-direction: column !important;
  flex-grow: 1 !important;
  height: 100% !important;
  width: 100% !important;
}
/* ICON POSITIONED EXACTLY AS IN PIC: Top-Left, 46x46px rounded square */
selector .elementor-icon-box-wrapper {
  text-align: left !important;
  align-items: flex-start !important;
}
selector .elementor-icon-box-icon {
  margin-left: 0 !important;
  margin-right: auto !important;
  margin-bottom: 18px !important;
  width: 46px !important;
  height: 46px !important;
  border-radius: 10px !important;
  background: rgba(23, 154, 158, 0.15) !important;
  border: 1px solid rgba(56, 212, 216, 0.25) !important;
  color: #38D4D8 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
  cursor: pointer !important;
}
/* USER REQUIREMENT: Hover GROW on the icon with GREEN fill */
selector .elementor-icon-box-icon:hover,
selector:hover .elementor-icon-box-icon {
  transform: scale(1.1) !important;
  background-color: #179A9E !important;
  border-color: #179A9E !important;
  color: #FFFFFF !important;
  box-shadow: 0 6px 20px rgba(23, 154, 158, 0.45) !important;
}
selector .elementor-icon-box-icon:hover svg,
selector .elementor-icon-box-icon:hover i,
selector:hover .elementor-icon-box-icon svg,
selector:hover .elementor-icon-box-icon i {
  color: #FFFFFF !important;
  fill: #FFFFFF !important;
}

